package pe.cruzroja.convocatorias.shared; import java.util.Map; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; @RestControllerAdvice public class ApiErrorHandler {@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("mensaje",e.getMessage(),"solucion","Revise los datos e inténtelo nuevamente."));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<Map<String,String>> conflict(IllegalStateException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("mensaje",e.getMessage(),"solucion","Actualice la página y revise el estado actual."));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,String>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("mensaje","Hay campos inválidos.","solucion","Corrija los campos señalados."));}}
